SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx IGNORE AS 
SELECT p.hospcode,p.PID, p.CID, p.NAME, p.LNAME, p.SEX, p.BIRTH
,p.HID, p.addr, p.check_vhid, p.NATION, p.TYPEAREA
,SEQ,DATE_SERV,DIDSTD,DNAME,CLINIC,dsf,O,GenericName,Class,AMOUNT,mgPerPackage,mgTotal 
FROM t_ddd_op d INNER JOIN t_person_db p ON d.HOSPCODE=p.HOSPCODE AND d.PID=p.PID
WHERE d.DATE_SERV BETWEEN @start_d AND @end_d;

SELECT
h.hoscode, h.hosname, d.PID, d.CID, d.NAME, d.LNAME, d.SEX, d.BIRTH
,d.HID, d.addr, d.check_vhid, d.NATION, d.TYPEAREA
,d.SEQ,d.DATE_SERV,d.DIDSTD,d.DNAME,d.CLINIC,d.dsf,d.O,d.GenericName
,d.Class,d.AMOUNT,d.mgPerPackage,d.mgTotal
FROM tx d
INNER JOIN chospital h ON d.hospcode = h.hoscode
WHERE 1=1 {where}
